def collapse_near_white_gaps(
    image: Image.Image,
    *,
    keep_gap: int = 28,
    min_gap: int = 72,
    ink_row_frac: float = 0.004,
    ink_value: int = 230,
) -> Image.Image:
    """Squeeze tall near-white bands left after wiping dotted answer lines.

    Empty-problem crops keep the stem and options but erase answer ruling.
    Without collapsing, multi-page questions show as sparse fragments with
    huge white voids that look truncated in review galleries.
    """
    arr = np.asarray(image.convert("RGB"), dtype=np.uint8)
    gray = arr.mean(axis=2)
    has_ink = (gray < ink_value).mean(axis=1) >= ink_row_frac
    keep = np.ones(len(has_ink), dtype=bool)
    y = 0
    height = len(has_ink)
    while y < height:
        if has_ink[y]:
            y += 1
            continue
        start = y
        while y < height and not has_ink[y]:
            y += 1
        gap = y - start
        if gap < min_gap:
            continue
        # Keep a short spacer at the start of the gap; drop the rest.
        keep[start + keep_gap : y] = False
    if bool(keep.all()):
        return image
    collapsed = arr[keep]
    if collapsed.size == 0:
        return image
    return Image.fromarray(collapsed)


def stitch_vertical(parts: list[Image.Image]) -> Image.Image:
    if len(parts) == 1:
        return parts[0]
    width = max(p.width for p in parts)
    height = sum(p.height for p in parts)
    out = Image.new("RGB", (width, height), (255, 255, 255))
    y = 0
    for part in parts:
        out.paste(part, (0, y))
        y += part.height
    return out


def content_box(image: Image.Image) -> tuple[int, int, int, int]:
    """Crop box excluding outer margins (pixel coords)."""
    w, h = image.size
    return (int(w * 0.035), int(h * 0.05), int(w * 0.95), int(h * 0.93))


def crop_questions(
    pages: list[Image.Image],
    starts: list[tuple[int, int, float]],
    *,
    clean_answer_lines: bool = True,
) -> dict[int, Image.Image]:
    results: dict[int, Image.Image] = {}
    if not starts:
        return results
    ends = starts[1:] + [(None, len(pages) - 1, pages[-1].size[1] * 0.93)]  # type: ignore

    for (qn, start_page, start_y), (next_qn, end_page, end_y) in zip(starts, ends):
        parts: list[Image.Image] = []
        for page_index in range(start_page, end_page + 1):
            img = pages[page_index]
            left, top_m, right, bottom_m = content_box(img)
            top = int(start_y - 8) if page_index == start_page else top_m
            if page_index == end_page and next_qn is not None:
                bottom = int(end_y - 10)
            else:
                bottom = bottom_m
            top = max(top_m, top)
            bottom = min(bottom_m, bottom)
            if bottom <= top + 30:
                continue
            part = img.crop((left, top, right, bottom))
            if clean_answer_lines:
                part = wipe_answer_lines(part)
                part = bleach_margins(part)
            g = np.asarray(part.convert("L"))
            if float((g < 225).mean()) < 0.008 and page_index != start_page:
                continue
            parts.append(part)
        if not parts:
            continue
        stitched = stitch_vertical(parts)
        if clean_answer_lines:
            stitched = collapse_near_white_gaps(stitched)
        results[qn] = trim_whitespace(stitched)
    return results

